--- index.html (The one page: hours, menu, the story, cakes, contact) ---
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Marlow Street Bakery</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <header class="top">
    <p class="mark">Marlow Street Bakery</p>
    <nav>
      <a href="#hours">Hours</a>
      <a href="#menu">Menu</a>
      <a href="#order">Cakes</a>
    </nav>
  </header>
  <main>
    <section class="hero">
      <h1>Marlow Street Bakery</h1>
      <p class="lead">A small neighborhood bakery at 14 Marlow Street, on the corner by the library. Everything is baked on site every morning.</p>
    </section>
    <section id="hours" class="card">
      <h2>Hours</h2>
      <dl>
        <dt>Tuesday to Friday</dt><dd>7:00 am to 3:00 pm</dd>
        <dt>Saturday and Sunday</dt><dd>8:00 am to 2:00 pm</dd>
        <dt>Monday</dt><dd>Closed</dd>
      </dl>
    </section>
    <section id="menu" class="card">
      <h2>Menu</h2>
      <ul class="menu">
        <li><span class="item">Country sourdough loaf</span><span class="price">$7.50</span></li>
        <li><span class="item">Seeded rye loaf</span><span class="price">$8.00</span></li>
        <li><span class="item">Butter croissant</span><span class="price">$3.75</span></li>
        <li><span class="item">Cardamom bun</span><span class="price">$4.25</span></li>
        <li><span class="item">Morning bun with orange zest</span><span class="price">$4.00</span></li>
        <li><span class="item">Sourdough focaccia slice</span><span class="price">$4.50</span></li>
        <li><span class="item">Filter coffee</span><span class="price">$2.75</span></li>
        <li><span class="item">Oat milk latte</span><span class="price">$4.75</span></li>
      </ul>
      <p class="note">The cardamom buns usually sell out by 11 am on weekends.</p>
    </section>
    <section id="story" class="card">
      <h2>Baked every morning</h2>
      <p>Everything is baked on site every morning, starting at 4 am. Teo bakes the bread with a sourdough starter he has kept alive since 2016.</p>
    </section>
    <section id="order" class="card">
      <h2>Cakes and special orders</h2>
      <p>Whole cakes and bread for parties need 48 hours' notice. Call us or come by the counter. We don't take orders by email yet.</p>
      <a class="call" href="tel:5550142290">Call (555) 014-2290</a>
    </section>
  </main>
  <footer>
    <p>Marlow Street Bakery, 14 Marlow Street</p>
    <p>Phone: (555) 014-2290</p>
  </footer>
</body>
</html>


